{
  "name": "@jacob-z/opencode-token-usage",
  "type": "module",
  "version": "0.1.0",
  "description": "OpenCode TUI plugin displaying subscription usage in the sidebar",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "subscription",
    "usage",
    "sidebar"
  ],
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "config": {
        "enabled": true
      }
    }
  },
  "files": [
    "README.md",
    "dist",
    "src"
  ],
  "scripts": {
    "build": "tsdown",
    "dev": "tsdown --watch",
    "typecheck": "tsc --noEmit",
    "lint": "eslint .",
    "lint:fix": "eslint . --fix",
    "version": "node -e \"require('fs').writeFileSync('src/_version.ts','// auto-generated\\nexport const PLUGIN_VERSION='+JSON.stringify(require('./package.json').version)+';\\n')\""
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0",
    "@opencode-ai/sdk": ">=1.14.0",
    "@opentui/core": ">=0.2.0",
    "@opentui/solid": ">=0.2.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@antfu/eslint-config": "^9.1.0",
    "@opencode-ai/plugin": "^1.17.14",
    "@opencode-ai/sdk": "^1.17.14",
    "@opentui/core": "^0.4.3",
    "@opentui/solid": "^0.4.3",
    "@unocss/eslint-plugin": "^66.7.5",
    "eslint": "^9.0.0",
    "eslint-plugin-format": "^2.0.1",
    "eslint-plugin-solid": "^0.14.5",
    "rolldown-plugin-solid": "^0.2.1",
    "solid-js": "^1.9.14",
    "tsdown": "^0.22.3",
    "tsx": "^4.22.3",
    "typescript": "^5.8.0",
    "unocss": "^66.7.5"
  }
}
